// Pure transforms from backend sources to the SDK's contracts/ files (design doc §C5 "How drift
// is caught", item 1). scripts/sync-contracts.ts does the I/O; everything here is unit-tested.

/** Header written into every generated file. Source paths only: commit SHAs live in sources.json. */
export function generatedHeader(sources: readonly string[]): string {
  return `Generated by scripts/sync-contracts.ts from ${sources.join(', ')}. Do not edit; run \`pnpm contracts:sync\`.`;
}

// ---------------------------------------------------------------------------------------------
// Observability registry (gincommon internal/obsregistry/registry.json)

interface RegistryLabel {
  description?: string;
  values?: string[];
  pattern?: string;
  max_values?: number;
  cardinality?: string;
}
interface RegistryMetric {
  name: string;
  tier: string;
  status: string;
  [key: string]: unknown;
}
export interface Registry {
  schema_version: number;
  const_labels: string[];
  required_labels: Record<string, string[]>;
  prohibited_labels: string[];
  prohibited_label_suffixes: string[];
  exempt_prefixes: string[];
  bucket_presets: Record<string, number[]>;
  labels: Record<string, RegistryLabel>;
  metrics: RegistryMetric[];
}

function requireLabel(registry: Registry, name: string, field: 'values' | 'pattern'): string[] | string {
  const label = registry.labels[name];
  const value = label?.[field];
  if (value === undefined) throw new Error(`registry.json: label ${name} has no ${field}`);
  return value;
}

/** Identity vocabulary for /core (design doc §0 rows 1-2, §C5 row 13). */
export function buildRegistryVocab(registry: Registry, source: string) {
  return {
    _generated: generatedHeader([source]),
    domains: requireLabel(registry, 'domain', 'values'),
    environments: requireLabel(registry, 'environment', 'values'),
    servicePattern: requireLabel(registry, 'service', 'pattern'),
    versionPattern: requireLabel(registry, 'version', 'pattern'),
  };
}

/**
 * The observability standard for /metrics (design doc §C5 row 15): everything the registration
 * checks need. Removed legacy entries are dropped: they can never be emitted.
 */
export function buildMetricRegistry(registry: Registry, source: string) {
  if (registry.schema_version !== 1) {
    throw new Error(`registry.json: schema_version ${registry.schema_version} is not supported (want 1)`);
  }
  return {
    _generated: generatedHeader([source]),
    schemaVersion: registry.schema_version,
    constLabels: registry.const_labels,
    requiredLabels: registry.required_labels,
    prohibitedLabels: registry.prohibited_labels,
    prohibitedLabelSuffixes: registry.prohibited_label_suffixes,
    exemptPrefixes: registry.exempt_prefixes,
    bucketPresets: registry.bucket_presets,
    labels: registry.labels,
    metrics: registry.metrics.filter((m) => !(m.tier === 'legacy' && m.status === 'removed')),
  };
}

/**
 * Differences between gincommon's registry (canonical) and fastapicommon's copy, as readable
 * lines. Empty when they agree. The SDK reads gincommon; a difference is a backend drift to report.
 */
export function diffRegistries(canonical: Registry, copy: Registry): string[] {
  const out: string[] = [];
  const keys = new Set([...Object.keys(canonical), ...Object.keys(copy)]) as Set<keyof Registry>;
  for (const key of keys) {
    if (key === 'labels') {
      const names = new Set([...Object.keys(canonical.labels ?? {}), ...Object.keys(copy.labels ?? {})]);
      for (const n of names) {
        if (JSON.stringify(canonical.labels?.[n]) !== JSON.stringify(copy.labels?.[n])) out.push(`labels.${n}`);
      }
    } else if (key === 'metrics') {
      const byName = (r: Registry) => new Map((r.metrics ?? []).map((m) => [m.name, JSON.stringify(m)]));
      const a = byName(canonical);
      const b = byName(copy);
      for (const n of new Set([...a.keys(), ...b.keys()])) {
        if (a.get(n) !== b.get(n)) out.push(`metrics.${n}`);
      }
    } else if (JSON.stringify(canonical[key]) !== JSON.stringify(copy[key])) {
      out.push(String(key));
    }
  }
  return out.sort();
}

// ---------------------------------------------------------------------------------------------
// go-probe contracts-export (public gincommon API)

interface ExportedType {
  domain: string;
  name: string;
  id: string;
  title: string;
  status: number;
  code: string;
}
export interface ContractsExport {
  problem: {
    contentType: string;
    defaultTypeBase: string;
    timestampLayout: string;
    platformDomain: string;
    codeRequestTimeout: string;
    maxRequestIdLength: number;
    types: ExportedType[];
    typeForStatus: ExportedType[];
  };
  headers: {
    request: { userId: string; tenantId: string; tenantRoles: string; requestId: string };
    response: { traceId: string; requestId: string };
    traceContext: string[];
  };
}

/** Problem registry and constants for /problem (design doc §C5 rows 1, 3-7). */
export function buildProblemTypes(exp: ContractsExport, source: string) {
  const p = exp.problem;
  if (p.types.length === 0) throw new Error('contracts-export: no platform problem types');
  return {
    _generated: generatedHeader([source]),
    contentType: p.contentType,
    defaultTypeBase: p.defaultTypeBase,
    timestampLayout: p.timestampLayout,
    platformDomain: p.platformDomain,
    codeRequestTimeout: p.codeRequestTimeout,
    // Platform types in registry order: id, title, status, code (design doc §C5 row 3).
    types: p.types,
    // TypeForStatus for every status Go's net/http knows. `id` is null for about:blank (no platform type).
    typeForStatus: p.typeForStatus.map((t) => ({
      status: t.status,
      id: t.id === '' ? null : t.id,
      title: t.title,
      code: t.code,
    })),
  };
}

// ---------------------------------------------------------------------------------------------
// Header limits and patterns (gincommon internal/core/domain, unexported)

/**
 * Integer constants declared as `Name = 123` in Go source. Throws when any name is missing or
 * declared more than once, so a refactor upstream fails the sync instead of passing silently.
 */
export function extractGoIntConsts(source: string, names: readonly string[], file: string): Record<string, number> {
  const out: Record<string, number> = {};
  for (const name of names) {
    const matches = [...source.matchAll(new RegExp(`^\\s*${name}\\s*=\\s*(\\d+)\\s*$`, 'gm'))];
    if (matches.length !== 1) {
      throw new Error(`${file}: expected exactly one integer constant ${name}, found ${matches.length}`);
    }
    out[name] = Number(matches[0]![1]);
  }
  return out;
}

/** The pattern of `var name = regexp.MustCompile(`...`)`. Throws unless declared exactly once. */
export function extractGoRegexp(source: string, varName: string, file: string): string {
  const matches = [...source.matchAll(new RegExp(`^var\\s+${varName}\\s*=\\s*regexp\\.MustCompile\\(\`([^\`]+)\`\\)`, 'gm'))];
  if (matches.length !== 1) {
    throw new Error(`${file}: expected exactly one regexp ${varName}, found ${matches.length}`);
  }
  return matches[0]![1]!;
}

export const HEADER_LIMIT_CONSTS = [
  'MaxHeaderValueLen',
  'MaxRoleLen',
  'MaxRolesHeaderLen',
  'MaxRoles',
  'MaxRequestIDLen',
] as const;

/** Header names, limits and patterns for /http and /core (design doc §C5 rows 8-10). */
export function buildHeaders(
  exp: ContractsExport,
  transportGo: string,
  validationGo: string,
  sources: { export: string; transport: string; validation: string },
) {
  const limits = extractGoIntConsts(transportGo, HEADER_LIMIT_CONSTS, sources.transport);
  if (limits.MaxRequestIDLen !== exp.problem.maxRequestIdLength) {
    throw new Error(
      `MaxRequestIDLen (${limits.MaxRequestIDLen}) differs from problem.MaxRequestIDLength (${exp.problem.maxRequestIdLength})`,
    );
  }
  const h = exp.headers;
  return {
    _generated: generatedHeader([sources.export, sources.transport, sources.validation]),
    request: { requestId: h.request.requestId, traceContext: h.traceContext },
    response: { traceId: h.response.traceId, requestId: h.response.requestId },
    // gincommon's identity headers: only a trusted gateway sets them; the browser never sends them.
    // The IAM ingress strip-list is added from the IAM sources (design doc §C5 row 8).
    identity: { userId: h.request.userId, tenantId: h.request.tenantId, tenantRoles: h.request.tenantRoles },
    limits: {
      headerValueMaxBytes: limits.MaxHeaderValueLen,
      requestIdMaxBytes: limits.MaxRequestIDLen,
      roleMaxBytes: limits.MaxRoleLen,
      rolesHeaderMaxBytes: limits.MaxRolesHeaderLen,
      maxRoles: limits.MaxRoles,
    },
    patterns: {
      requestId: extractGoRegexp(validationGo, 'requestIDPattern', sources.validation),
      roleToken: extractGoRegexp(validationGo, 'roleTokenPattern', sources.validation),
    },
  };
}

// ---------------------------------------------------------------------------------------------
// Log field names (gincommon middleware/logging.go)

/** Keys of the `fields := map[string]interface{}{ ... }` literal in gincommon's request logger. */
export function extractLogFieldKeys(source: string, file: string): string[] {
  const start = source.indexOf('fields := map[string]interface{}{');
  if (start < 0) throw new Error(`${file}: request log fields map not found`);
  const end = source.indexOf('\n\t\t\t}', start);
  if (end < 0) throw new Error(`${file}: end of request log fields map not found`);
  const keys = [...source.slice(start, end).matchAll(/^\s*"([a-z_]+)":/gm)].map((m) => m[1]!);
  if (keys.length === 0) throw new Error(`${file}: request log fields map has no keys`);
  return keys;
}

/** Log field names for /logging (design doc §C5 row 16): the SDK's correlation fields must match. */
export function buildLogFields(loggingGo: string, source: string) {
  const keys = extractLogFieldKeys(loggingGo, source);
  for (const required of ['trace_id', 'request_id']) {
    if (!keys.includes(required)) throw new Error(`${source}: request log has no ${required} field`);
  }
  return {
    _generated: generatedHeader([source]),
    correlation: { traceId: 'trace_id', requestId: 'request_id' },
    // Every field of gincommon's http_request log line, in source order. `path` there is the
    // server route template; the SDK's page route is logged as `page_route`, never `path`.
    httpRequest: keys,
  };
}

// ---------------------------------------------------------------------------------------------
// Log redaction (gincommon internal/core/service/log_sanitizer.go, unexported)

function sliceBetween(source: string, start: string, end: string, file: string, what: string): string {
  const i = source.indexOf(start);
  if (i < 0) throw new Error(`${file}: ${what} not found`);
  const j = source.indexOf(end, i + start.length);
  if (j < 0) throw new Error(`${file}: end of ${what} not found`);
  return source.slice(i + start.length, j);
}

/**
 * The redaction rule of gincommon's log sanitizer (design doc §0 row 4, §C5 row 12): exact
 * sensitive keys, sensitive substrings, the `key` / `*_key` rule, the replacement value and the
 * string limit. Every piece is read from the source and checked, so an upstream change fails the
 * sync instead of being missed.
 */
export function buildRedaction(sanitizerGo: string, source: string) {
  const keysBlock = sliceBetween(sanitizerGo, 'var sensitiveLogKeys = map[string]struct{}{', '\n}', source, 'sensitiveLogKeys');
  const exactKeys = [...keysBlock.matchAll(/^\s*"([^"]+)":\s*\{\},?\s*$/gm)].map((m) => m[1]!);
  const ruleBlock = sliceBetween(sanitizerGo, 'func isSensitiveLogKey(key string) bool {', '\n}', source, 'isSensitiveLogKey');
  const substrings = [...ruleBlock.matchAll(/strings\.Contains\(k, "([^"]+)"\)/g)].map((m) => m[1]!);
  const exactKeyRule = /k == "key" \|\| strings\.HasSuffix\(k, "_key"\)/.test(ruleBlock);
  const normalises = /strings\.ToLower\(strings\.TrimSpace\(key\)\)/.test(ruleBlock);
  const redacted = /out\[k\] = "(\[[A-Z]+\])"/.exec(sanitizerGo)?.[1];
  const maxBytes = Number(/const maxLen = (\d+)/.exec(sanitizerGo)?.[1]);
  const stripsControl = /unicode\.IsControl\(r\)/.test(sanitizerGo);
  if (exactKeys.length === 0) throw new Error(`${source}: no exact sensitive keys found`);
  if (substrings.length === 0) throw new Error(`${source}: no sensitive substrings found`);
  if (!exactKeyRule) throw new Error(`${source}: the key / *_key rule changed`);
  if (!normalises) throw new Error(`${source}: key normalisation (TrimSpace + ToLower) changed`);
  if (!redacted) throw new Error(`${source}: redaction placeholder not found`);
  if (!Number.isInteger(maxBytes) || maxBytes <= 0) throw new Error(`${source}: SanitizeString maxLen not found`);
  if (!stripsControl) throw new Error(`${source}: SanitizeString no longer strips unicode.IsControl (Cc)`);
  return {
    _generated: generatedHeader([source]),
    // Keys are trimmed and lower-cased before matching.
    exactKeys,
    substrings,
    // Also sensitive: the key "key" itself and any key ending in this suffix.
    keySuffix: '_key',
    redacted,
    // SanitizeString: remove Unicode Cc characters, then truncate to this many UTF-8 bytes.
    stringMaxBytes: maxBytes,
  };
}

/**
 * A TypeScript module with the contracts the SDK's code reads, as `as const` literals so the
 * types are exact (e.g. `Domain` is the union of registry domains). Generated with the JSON files,
 * so it can never drift from them (design doc §C5: "TS constants are generated from contracts/").
 */
export function buildTsConstants(contracts: Record<string, unknown>, sources: readonly string[]): string {
  const strip = (v: unknown): unknown => {
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      return Object.fromEntries(Object.entries(v).filter(([k]) => k !== '_generated'));
    }
    return v;
  };
  const lines = [`// ${generatedHeader(sources)}`, ''];
  for (const [name, value] of Object.entries(contracts)) {
    lines.push(`export const ${name} = ${JSON.stringify(strip(value), null, 2)} as const;`, '');
  }
  return lines.join('\n');
}

/** Stable JSON text for a generated file. */
export function toJsonText(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}
